  f=$1; re=$2; [ -f "$f" ] || return 0
  grep -Eq "$re" "$f" || return 0
  tma_bk "$f"; t="$f.tma.$$"
  awk -v re="$re" '$0 ~ re && $0 !~ /^[[:space:]]*#/ { print "#TMAegis# " $0; next } { print }' "$f" > "$t" || { rm -f "$t"; return 1; }
  cat "$t" > "$f"; rm -f "$t"; return 0
}
for f in /var/spool/mqueue/; do
  [ -e "$f" ] || continue
  chmod g-rwx,o-rwx "$f"
  x=$(ls -ld "$f" | awk '{print $3}'); case "|root|" in *"|$x|"*) ;; *) chown root "$f";; esac
  x=$(ls -ld "$f" | awk '{print $4}'); case "|system|" in *"|$x|"*) ;; *) chgrp system "$f";; esac
done

